// MosaicPlatformEffects.kt -- the operating-system capabilities Mosaic provides
// on Android, shared by every generated app (UI87 §7, UI89 §3.8).
//
// Generated by mosaic-app-bindings; do not edit in a generated project. This
// is Android's half of the platform library: the Storage Access Framework's
// document picker, as the router's MosaicDocumentPicker. The contracts, the
// rules a request must meet and the router are MosaicFileEffects.kt's, the
// same file the desktop project compiles; the desktop's own half (AWT dialogs)
// never reaches Android.
//
//   files.open  ACTION_OPEN_DOCUMENT (ActivityResultContracts.OpenDocument),
//               filtered on the request's MIME types (any document when none
//               map); the bytes come from the provider's file descriptor,
//               bounded while reading -- a provider's reported size is not
//               trusted -- and watched: no byte for MOSAIC_STALL_MILLIS and
//               the read is stopped and the request fails (UI89 §3.8).
//   files.save  checked first, exactly as on the desktop; then
//               ACTION_CREATE_DOCUMENT with the suggested name and its type,
//               and the bytes go to the provider's descriptor ("wt"), in
//               watched 64 KiB pieces. The answer's
//               name is the provider's display name, which may differ from
//               the suggestion (most providers add " (1)" rather than replace).
//               A provider owns the file, and SAF offers no atomic replace, so
//               there is no temporary-and-rename here. A write that fails is
//               a failure and nothing more: the picker may have handed back a
//               document the person already had (DocumentsUI asks "replace?"),
//               and deleting it would lose its history with the bytes.
//
// Threading
// ---------
//
// The router shows a picker from the main thread, which is where the activity
// result registry answers too; the document is read or written on a
// background thread, and the outcome is handed back to the main thread before
// the effect is completed (the host's props-changed handler writes Compose
// state). The launchers are registered when the activity is created, before
// it starts, as the registry requires; MosaicActivity does that and installs
// the router when the host loads.

import android.app.Activity
import android.content.ActivityNotFoundException
import android.content.ContentResolver
import android.content.Context
import android.content.Intent
import android.content.res.AssetFileDescriptor
import android.net.Uri
import android.os.CancellationSignal
import android.os.Handler
import android.os.Looper
import android.provider.OpenableColumns
import androidx.activity.ComponentActivity
import androidx.activity.result.ActivityResultLauncher
import androidx.activity.result.contract.ActivityResultContract
import androidx.activity.result.contract.ActivityResultContracts
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicBoolean

/**
 * `ACTION_CREATE_DOCUMENT` with the type and title chosen per request:
 * `ActivityResultContracts.CreateDocument` fixes its type when registered,
 * and a launcher must be registered before the activity starts.
 */
private class MosaicCreateDocument : ActivityResultContract<Pair<String, String>, Uri?>() {
    override fun createIntent(context: Context, input: Pair<String, String>): Intent =
        Intent(Intent.ACTION_CREATE_DOCUMENT)
            .addCategory(Intent.CATEGORY_OPENABLE)
            .setType(input.first)
            .putExtra(Intent.EXTRA_TITLE, input.second)

    override fun parseResult(resultCode: Int, intent: Intent?): Uri? =
        if (resultCode == Activity.RESULT_OK) intent?.data else null
}

/**
 * The Storage Access Framework's picker as the router's [MosaicDocumentPicker].
 * Construct it in the activity's `onCreate`, before the activity starts.
 *
 * One request at a time, which the router already guarantees; the `done` of
 * the request in flight is held here until the registry answers, and only
 * ever touched on the main thread.
 */
class MosaicAndroidDocumentPicker(activity: ComponentActivity) : MosaicDocumentPicker {
    // The application's resolver, not the activity's: a read or write that
    // outlives the activity must not keep it alive.
    private val resolver: ContentResolver = activity.applicationContext.contentResolver
    private var openDone: ((MosaicOpenedDocument?) -> Unit)? = null
    private var createDone: ((MosaicSaveTarget?) -> Unit)? = null

    private val openLauncher: ActivityResultLauncher<Array<String>> =
        activity.registerForActivityResult(ActivityResultContracts.OpenDocument()) { uri ->
            val done = openDone ?: return@registerForActivityResult
            openDone = null
            done(uri?.let { MosaicContentDocument(resolver, it) })
        }

    private val createLauncher: ActivityResultLauncher<Pair<String, String>> =
        activity.registerForActivityResult(MosaicCreateDocument()) { uri ->
            val done = createDone ?: return@registerForActivityResult
            createDone = null
            done(uri?.let { MosaicContentTarget(resolver, it) })
        }

    /**
     * True while a picker is open and its answer has not arrived: what the
     * activity checks before failing the request when it is destroyed.
     */
    val isWaiting: Boolean get() = openDone != null || createDone != null

    override fun open(accept: MosaicAccept, done: (MosaicOpenedDocument?) -> Unit) {
        openDone = done
        try {
            openLauncher.launch(accept.mimeTypes.ifEmpty { listOf("*/*") }.toTypedArray())
        } catch (missing: ActivityNotFoundException) {
            openDone = null
            throw MosaicFileFailure("there is no app to choose a file with")
        } catch (error: Throwable) {
            // Not waiting on anything that failed to launch (a launcher the
            // destroyed activity already unregistered, say).
            openDone = null
            throw error
        }
    }

    override fun create(request: MosaicSaveRequest, done: (MosaicSaveTarget?) -> Unit) {
        // The name's own type when the request accepts it (or accepts
        // anything); otherwise the first type it accepts.
        val named = mosaicMimeTypeForName(request.suggestedName)
        val mimeType = if (request.accept.mimeTypes.isEmpty() || named in request.accept.mimeTypes) {
            named
        } else {
            request.accept.mimeTypes.first()
        }
        createDone = done
        try {
            createLauncher.launch(mimeType to request.suggestedName)
        } catch (missing: ActivityNotFoundException) {
            createDone = null
            throw MosaicFileFailure("there is no app to save a file with")
        } catch (error: Throwable) {
            createDone = null
            throw error
        }
    }
}

/**
 * A document's display name, as its provider reports it -- any provider, so
 * the app is told it only when it is an ordinary name: the part after any `/`
 * or `\`, not `.` or `..`, no control, line or paragraph separator, lone
 * surrogate or bidirectional control (a right-to-left override would disguise
 * it), at most 255 UTF-16 units. Other format characters are part of ordinary
 * writing -- the zero-width joiners of Persian and Devanagari and of emoji
 * sequences, a soft hyphen -- and pass, as does a character newer than the
 * device's Unicode tables.
 * Anything else, or nothing, is null, and the app is told "document".
 */
private fun mosaicDisplayName(resolver: ContentResolver, uri: Uri): String? {
    // Watched like a read (UI89 §3.8): a provider that never answers is
    // cancelled, and the app is told "document".
    val reported = try {
        MosaicStallWatch().use { watch ->
            val asking = CancellationSignal()
            watch.stopWith { asking.cancel() }
            resolver.query(uri, arrayOf(OpenableColumns.DISPLAY_NAME), null, null, null, asking)
                ?.use { cursor -> if (cursor.moveToFirst() && !cursor.isNull(0)) cursor.getString(0) else null }
        }
    } catch (error: Exception) {
        null
    } ?: return null
    val name = reported.substringAfterLast('/').substringAfterLast('\\')
    if (name.isBlank() || name == "." || name == ".." || name.length > 255) return null
    val unsafe = name.codePoints().anyMatch { point ->
        point in MOSAIC_BIDI_CONTROLS || when (Character.getType(point).toByte()) {
            Character.CONTROL, Character.LINE_SEPARATOR,
            Character.PARAGRAPH_SEPARATOR, Character.SURROGATE -> true
            else -> false
        }
    }
    return name.takeUnless { unsafe }
}

/**
 * The characters that reorder text: ARABIC LETTER MARK, LEFT-TO-RIGHT and
 * RIGHT-TO-LEFT MARK, the embeddings and overrides, and the isolates.
 */
private val MOSAIC_BIDI_CONTROLS: Set<Int> =
    setOf(0x061C, 0x200E, 0x200F) + (0x202A..0x202E) + (0x2066..0x2069)

/** A MIME type a provider reports, when it is shaped like one (and short). */
private val MOSAIC_MIME_SHAPE = Regex("^[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]{0,126}/[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]{0,126}$")

/** A chosen document, read through its provider. */
private class MosaicContentDocument(
    private val resolver: ContentResolver,
    private val uri: Uri,
) : MosaicOpenedDocument {
    // Asked of the provider when first needed -- on the background thread,
    // after the read -- never on the main thread.
    override val name: String by lazy { mosaicDisplayName(resolver, uri) ?: "document" }
    override val mimeType: String? by lazy {
        try {
            resolver.getType(uri)?.takeIf { MOSAIC_MIME_SHAPE.matches(it) }
        } catch (error: Exception) {
            null
        }
    }

    // Watched (UI89 §3.8): a provider that stops serving -- or never finishes
    // opening -- is stopped after MOSAIC_STALL_MILLIS without a byte, and the
    // request fails instead of holding the one file operation for ever.
    override fun read(limit: Long): ByteArray? = mosaicWatchedTransfer(
        resolver,
        uri,
        mode = "r",
        unopened = "couldn't read the selected file",
        stalled = "the selected file stopped arriving",
    ) { descriptor, watch ->
        mosaicReadBounded(mosaicWatchedInput(descriptor.createInputStream(), watch), limit)
    }
}

/** A document the person created to save into, written through its provider. */
private class MosaicContentTarget(
    private val resolver: ContentResolver,
    private val uri: Uri,
) : MosaicSaveTarget {
    override val name: String by lazy { mosaicDisplayName(resolver, uri) ?: "document" }

    // Watched like a read: a provider that stops taking bytes, or never
    // finishes opening, fails the save rather than holding it (UI89 §3.8).
    override fun write(bytes: ByteArray) = mosaicWatchedTransfer(
        resolver,
        uri,
        mode = "wt",
        unopened = "couldn't save the file",
        stalled = "the file stopped saving",
    ) { descriptor, watch ->
        mosaicWriteWatched(descriptor.createOutputStream(), bytes, watch)
    }
}

/**
 * One read or write of a document through its provider, watched (UI89 §3.8):
 * opened with a `CancellationSignal` the watch cancels if the provider never
 * finishes opening; then [transfer] runs on the descriptor, which the watch
 * closes if no byte moves for `MOSAIC_STALL_MILLIS`.
 *
 * The descriptor is closed exactly once, whichever comes first:
 *
 * | who          | how                         | the provider is told |
 * |--------------|-----------------------------|----------------------|
 * | the watch    | `closeWithError` (stalled)  | the transfer failed  |
 * | the transfer | `close` (finished, or threw) | it ended normally    |
 *
 * A transfer that finished claims the close before its result is trusted, so
 * the provider and the app are never told different things.
 *
 * Once, because two threads closing one descriptor can close a reused fd
 * number. With an error, because a provider reading a save through a reliable
 * pipe would otherwise take a stalled, truncated save for a finished one.
 * [transfer] makes its stream from the descriptor and must not close it.
 */
private fun <T> mosaicWatchedTransfer(
    resolver: ContentResolver,
    uri: Uri,
    mode: String,
    unopened: String,
    stalled: String,
    transfer: (AssetFileDescriptor, MosaicStallWatch) -> T,
): T = MosaicStallWatch().use { watch ->
    val opening = CancellationSignal()
    watch.stopWith { opening.cancel() }
    try {
        val descriptor = resolver.openAssetFileDescriptor(uri, mode, opening)
            ?: throw MosaicFileFailure(unopened)
        val closed = AtomicBoolean(false)
        watch.stopWith {
            if (closed.compareAndSet(false, true)) {
                descriptor.parcelFileDescriptor.closeWithError("the transfer stalled")
            }
        }
        val result = try {
            transfer(descriptor, watch)
        } catch (error: Throwable) {
            if (closed.compareAndSet(false, true)) runCatching { descriptor.close() }
            throw error
        }
        // Claim the close before trusting the result: either the watch
        // already fired -- the bytes may have come from a reused descriptor,
        // and the provider was told it failed -- or the transfer closes it,
        // normally, and the watch can no longer report an error.
        if (!closed.compareAndSet(false, true)) throw MosaicFileFailure(stalled)
        runCatching { descriptor.close() }
        result
    } catch (failure: MosaicFileFailure) {
        throw failure
    } catch (error: Exception) {
        if (watch.stalled) throw MosaicFileFailure(stalled)
        throw error
    }
}

// One background thread for every read and write: requests are one at a time
// anyway, and a daemon thread never keeps the process alive.
private val mosaicFileEffectsThread: ExecutorService = Executors.newSingleThreadExecutor { work ->
    Thread(work, "mosaic-file-effects").apply { isDaemon = true }
}

/**
 * Install the platform library on [host], answering through [picker] (the
 * activity's). Package `[host_effects]` handlers are desktop-only for now
 * (UI89 §3.5), so the standard kinds always come here, and any other kind is
 * failed by the host as unanswered. Returns the router -- the one already
 * installed, when there is one -- so the activity can fail a request whose
 * picker can no longer answer.
 */
fun installMosaicPlatformEffects(
    host: MosaicPlatformEffectHost,
    picker: MosaicDocumentPicker,
): MosaicPlatformRouter {
    (host.effectHandler as? MosaicPlatformRouter)?.let { return it }
    val main = Handler(Looper.getMainLooper())
    val router = MosaicPlatformRouter(
        host,
        host.effectHandler,
        null,
        picker,
        { work -> main.post(work) },
        { work -> mosaicFileEffectsThread.execute(work) },
    )
    host.effectHandler = router
    return router
}
